#!/usr/bin/env bash
# One-time setup when the Codespace (or any Ubuntu box) is created.
# Safe to run again: it never overwrites an existing deploy/switch/.env.
set -euo pipefail
cd "$(dirname "$0")/.."

ENV=deploy/switch/.env
if [ ! -f "$ENV" ]; then
  hex() { openssl rand -hex "$1"; }
  ADMIN_PASSWORD="$(hex 12)"
  cat > "$ENV" <<ENVEOF
# Generated by deploy/setup.sh. Secrets: never commit this file.
SWITCH_VERSION=0.31.0
COMPOSE_PROFILES=gateway
DB_NAME=switch
DB_USER=switch_app
DB_PASSWORD=$(hex 24)
DB_OWNER_USER=postgres
DB_OWNER_PASSWORD=$(hex 24)
AGENT_REGISTRATION_TOKEN=$(hex 32)
SECRET_KEYS=k1:$(hex 32)
CONTROLLER_TOKEN_SECRET=$(hex 32)
FEATURE_FLAGS_ENABLED=agent_management,agent_chats,switch_buddy,follow_the_conversation,service_connections
GATEWAY_ADMIN_EMAIL=admin@switch.local
GATEWAY_ADMIN_PASSWORD=$ADMIN_PASSWORD
# Console on your Mac and the agents here both reach the server at localhost:8000
# (your Mac through a forwarded port), so one address works for everyone.
FRONTEND_BASE_URL=http://localhost:8000
GATEWAY_PUBLIC_URL=http://localhost:8000
GATEWAY_COOKIE_SECURE=false
TELEMETRY_ENABLED=false
ENVEOF
  chmod 600 "$ENV"
  echo "Created $ENV. Gateway admin: admin@switch.local / $ADMIN_PASSWORD"
fi

# Claude Code (the agents' runtime) and the studio CLI.
npm install -g @anthropic-ai/claude-code
npm link

# Figma's remote MCP server. Sign in once with: claude, then /mcp.
claude mcp get figma >/dev/null 2>&1 || claude mcp add --scope user --transport http figma https://mcp.figma.com/mcp

echo "Setup done. Next: see deploy/CODESPACES.md"
